steps.body:
`lab07.py` নামে নিচের ফাইলটা বানাও। এখানে `read_log` একটা কৃত্রিম বড় output দেয়; `prune` পুরোনো `tool_result` ছাঁটে (শেষ `KEEP_LAST`টা বাদে); `summarise` ইতিহাসকে একটা সারসংক্ষেপ-message দিয়ে বদলায়।

```python
import os
import anthropic

client = anthropic.Anthropic()
MODEL = os.environ["CLAUDE_MODEL"]
THRESHOLD = int(os.environ.get("THRESHOLD", "5000"))   # input token সীমা
KEEP_LAST = 2                                            # কয়টা সাম্প্রতিক tool result রাখব
PLACEHOLDER = "[পুরোনো tool result সরানো হয়েছে]"

TOOLS = [{
    "name": "read_log",
    "description": "একটা দিনের order log ফেরত দেয়। দিন সংখ্যা (day) দাও।",
    "input_schema": {
        "type": "object",
        "properties": {"day": {"type": "integer"}},
        "required": ["day"],
    },
}]

TASK = ("read_log tool দিয়ে day 1 থেকে day 8 পর্যন্ত প্রতিটা দিনের log একটা একটা করে পড়ো। "
        "শেষে প্রতিটা দিনের জন্য এক লাইনে সংক্ষেপ লেখো।")


def read_log(day: int) -> str:
    # কৃত্রিম বড় output (~১,০০০+ token)
    return f"[day {day}] " + " ".join(f"ORDER-{day}-{i}: paid, packed, shipped." for i in range(150))


def size(messages) -> int:
    r = client.messages.count_tokens(model=MODEL, messages=messages, tools=TOOLS)
    return r.input_tokens


def prune(messages):
    idx = [i for i, m in enumerate(messages)
           if m["role"] == "user" and isinstance(m["content"], list)
           and any(isinstance(b, dict) and b.get("type") == "tool_result" for b in m["content"])]
    for i in idx[:-KEEP_LAST]:
        for b in messages[i]["content"]:
            if isinstance(b, dict) and b.get("type") == "tool_result":
                b["content"] = PLACEHOLDER          # tool_use_id অক্ষত থাকে
    return messages


def as_text(messages) -> str:
    lines = []
    for m in messages:
        c = m["content"]
        if isinstance(c, str):
            lines.append(f'{m["role"]}: {c}')
            continue
        for b in c:
            t = b["type"] if isinstance(b, dict) else b.type
            if t == "text":
                lines.append(f'{m["role"]}: ' + (b["text"] if isinstance(b, dict) else b.text))
            elif t == "tool_use":
                lines.append("assistant ডাকল: " + (b["name"] if isinstance(b, dict) else b.name))
    return "\n".join(lines)


def summarise(messages):
    r = client.messages.create(
        model=MODEL, max_tokens=500,
        messages=[{"role": "user", "content":
                   "নিচের কাজের ইতিহাস ১৫০ শব্দের মধ্যে সংক্ষেপ করো। রাখো: লক্ষ্য, এ পর্যন্ত পাওয়া ফল, "
                   "বাকি কাজ। raw log বাদ দাও।\n\n" + as_text(messages)}],
    )
    summary = "".join(b.text for b in r.content if b.type == "text")
    return [{"role": "user", "content": "[আগের কাজের সারসংক্ষেপ]\n" + summary +
             "\n\nএই সারসংক্ষেপ ধরে মূল কাজটা চালিয়ে যাও।\nমূল কাজ: " + TASK}]


messages = [{"role": "user", "content": TASK}]
for step in range(1, 21):
    n = size(messages)
    print(f"step {step:2d}: input_tokens = {n}")
    if n > THRESHOLD:
        messages = prune(messages)
        n2 = size(messages)
        print(f"         prune  -> {n2}")
        if n2 > THRESHOLD:
            messages = summarise(messages)
            print(f"         summary -> {size(messages)}")
    resp = client.messages.create(model=MODEL, max_tokens=1024, tools=TOOLS, messages=messages)
    messages.append({"role": "assistant", "content": resp.content})
    if resp.stop_reason != "tool_use":
        print("\n--- চূড়ান্ত উত্তর ---")
        print("".join(b.text for b in resp.content if b.type == "text"))
        break
    results = [{"type": "tool_result", "tool_use_id": b.id, "content": read_log(b.input["day"])}
               for b in resp.content if b.type == "tool_use"]
    messages.append({"role": "user", "content": results})
```

**লক্ষ করো:** compaction শুধু loop-এর শুরুতে হয়, যখন শেষ message একটা `tool_result` (কোনো `tool_use` অসম্পূর্ণ নেই)। নইলে `tool_use`/`tool_result` জোড়া ভেঙে 400 error আসত।
